<?php
namespace App\Controller;
use App\Core\{Auth,Controller};use App\Repository\{LecturerRepository,FacultyRepository};
class LecturerController extends Controller {public function __construct(private \PDO $pdo){} private function repo():LecturerRepository{return new LecturerRepository($this->pdo);} private function validate(array $d,bool $create):array{$e=[];if($d['lecturer_code']==='')$e['lecturer_code']='Mã giảng viên là bắt buộc.';elseif(!preg_match('/^[A-Za-z0-9._-]{2,30}$/',$d['lecturer_code']))$e['lecturer_code']='Mã giảng viên 2-30 ký tự, chỉ gồm chữ, số, ., _, -.';if($d['full_name']==='')$e['full_name']='Họ tên là bắt buộc.';elseif(mb_strlen($d['full_name'])>100)$e['full_name']='Họ tên tối đa 100 ký tự.';if(!filter_var($d['faculty_id']??null,FILTER_VALIDATE_INT))$e['faculty_id']='Vui lòng chọn khoa.';if($create){if($d['username']===''||strlen($d['username'])>50)$e['username']='Tên đăng nhập bắt buộc, tối đa 50 ký tự.';if(strlen($d['password'])<6)$e['password']='Mật khẩu tối thiểu 6 ký tự.';}elseif($d['password']!==''&&strlen($d['password'])<6)$e['password']='Mật khẩu mới tối thiểu 6 ký tự.';return$e;}
 public function index():void{Auth::requireRole('admin');$q=trim($_GET['q']??'');$page=max(1,(int)($_GET['page']??1));$r=$this->repo();$total=$r->count($q);[$page,$per,$off,$pages]=paginate($page,8,$total);$this->view('admin/lecturers/index',['rows'=>$r->findPage($q,$per,$off),'q'=>$q,'page'=>$page,'pages'=>$pages]);}
 public function create():void{$this->form(true);}public function edit():void{$this->form(false);}private function form(bool $create):void{Auth::requireRole('admin');$r=$this->repo();$id=(int)($_GET['id']??0);$ex=$create?null:$r->findById($id);if(!$create&&!$ex){http_response_code(404);exit('Không tìm thấy giảng viên.');}$d=$ex?array_merge($ex,['password'=>'']):['lecturer_code'=>'','full_name'=>'','faculty_id'=>'','username'=>'','password'=>'','status'=>1];$errs=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$d=['lecturer_code'=>strtoupper(post_string('lecturer_code')),'full_name'=>post_string('full_name'),'faculty_id'=>post_int('faculty_id'),'username'=>strtolower(post_string('username')),'password'=>(string)($_POST['password']??''),'status'=>isset($_POST['status'])?1:0];$errs=$this->validate($d,$create);if(!$errs){try{if($create)$r->create($d);else$r->update($id,$d);flash('success',$create?'Đã thêm giảng viên.':'Đã cập nhật giảng viên.');clearFormMemory();redirect('admin/lecturers');}catch(\Throwable$e){$errs['general']='Mã giảng viên hoặc tên đăng nhập có thể đã tồn tại.';}}rememberForm($d,$errs);}else clearFormMemory();$this->view('admin/lecturers/form',['create'=>$create,'data'=>$d,'errors'=>$errs,'faculties'=>(new FacultyRepository($this->pdo))->findAll()]);}
 public function delete():void{Auth::requireRole('admin');verify_csrf();$id=post_int('id');try{$this->repo()->delete($id);flash('success','Đã xóa giảng viên.');}catch(\Throwable$e){flash('error','Không thể xóa giảng viên vì còn lớp học phần.');}redirect('admin/lecturers');}
}
